@app.get("/health")
def health():
    return {"status":"ok", "version":"0.4.0", "public_checks":True, "private_data_connectors":False}

def allowed_public_host(url: str) -> str:
    try:
        u = urlsplit(url)
    except ValueError:
        raise HTTPException(400, "URL invalid hai")
    if u.scheme != "https" or not u.hostname or u.username or u.password or u.port not in (None, 443):
        raise HTTPException(400, "Sirf public HTTPS URLs allowed hain")
    hostname = u.hostname.lower().rstrip('.')
    if not re.fullmatch(r'[a-z0-9.-]{1,253}', hostname):
        raise HTTPException(400, "Hostname invalid hai")
    allowed = {s.strip().lower() for s in os.getenv('AUDIT_ALLOWED_HOSTS','').split(',') if s.strip()}
    if hostname not in allowed:
        raise HTTPException(403, "Domain allowlist mein nahi hai. AUDIT_ALLOWED_HOSTS configure karein")
    try:
        results=socket.getaddrinfo(hostname,443,proto=socket.IPPROTO_TCP)
        ips={item[4][0] for item in results}
        if not ips or not all(ipaddress.ip_address(ip).is_global for ip in ips):
            raise ValueError('Private/non-public address')
    except Exception:
        raise HTTPException(400, "Public destination validate nahi hui")
    return url

@app.post('/api/public-check')
async def public_check(body: URLCheck, x_auditor_key: str | None = Header(default=None)):
    expected = os.getenv('AUDITOR_API_KEY', '')
    if len(expected)<24 or not x_auditor_key:
        raise HTTPException(403, "Auditor key configured nahi hai")
    import hmac
    if not hmac.compare_digest(expected,x_auditor_key):
        raise HTTPException(403, "Invalid owner key")
    target=allowed_public_host(body.url)
    try:
        # No redirects, no proxies, no cookies, no custom headers, limited content.
        # A domain allowlist is essential: do not allow arbitrary hosts.
        async with httpx.AsyncClient(timeout=8.0,follow_redirects=False,trust_env=False) as client:
            async with client.stream('GET',target,headers={'Accept':'text/html,application/xhtml+xml'}) as response:
                status=response.status_code
                ct=response.headers.get('content-type','')[:160]
                redirect=response.headers.get('location','')[:300]
                sample=b''
                async for chunk in response.aiter_bytes():
                    sample+=chunk[:max(0,16384-len(sample))]
                    if len(sample)>=16384:break
        return {'status_code':status,'content_type':ct,'redirect_to':redirect,'final_url':target,
                'checked_at':datetime.now(timezone.utc).isoformat(), 'bytes_sampled':len(sample),
                'proof_type':'Direct HTTP response. Not a functional or authenticated audit.'}
    except httpx.HTTPError as exc:
        raise HTTPException(502, 'URL read nahi ho paaya: '+type(exc).__name__)
